    protected var session: MockHttpSession? = null

    private var signedIn = false

    companion object {
        /** A test's values are its own (logins, unique fields): each run starts somewhere new. */
        private val SEQUENCE = AtomicLong(ThreadLocalRandom.current().nextLong(1L shl 30))

        private const val PRINCIPAL = "/api/v1/shop/agent"
