     * (CurrentUser.runAsSystem). The tests check what the model declares, not who
     * may ask; sign in your way here if the application does.
     */
    protected open fun signIn() {
        val principal = obj("login", text(12), "secret", text(12))
        principal["grade"] = "ADMIN"
        val made = asSystem(MockMvcRequestBuilders.post(PRINCIPAL)
            .contentType(MediaType.APPLICATION_JSON).content(json(principal)))
        Assertions.assertTrue(ok(made)) { "the administrator to sign in as was not made: " + answer(made) }
        val signedInAs = mvc.perform(request(MockMvcRequestBuilders.post(PRINCIPAL + "/signin")
            .contentType(MediaType.APPLICATION_JSON).accept(MediaType.APPLICATION_JSON)
            .content(json(obj("login", principal["login"], "secret", principal["secret"]))))).andReturn()
        Assertions.assertTrue(ok(signedInAs)) { "the generated sign-in refused the administrator: " + answer(signedInAs) }
        session = signedInAs.request.getSession(false) as MockHttpSession?
