    /** A step to the state the test starts from: given, or the test is aborted when a rule of the application's refuses it. */
    protected fun given(step: MvcResult) = succeeded(step, "a step to the state the test starts from")

    /** The command was given: 2xx. */
    protected fun assertMoved(result: MvcResult) = succeeded(result, "the command")

    /**
     * 2xx. Refused by a rule of the application's own - a check its code makes, a unique value
